template:
@php
    $address = is_string($source) ? trim($source) : '';
    $clip = is_array($file) && ! empty($file['url']) ? $file : null;
    $picture = is_array($poster) && ! empty($poster['url']) ? $poster : null;
    $shape = is_string($ratio) && trim($ratio) !== '' ? trim($ratio) : null;
@endphp
<section class="b-showcase-video b-showcase-video--{{ $width === 'narrow' ? 'narrow' : 'full' }}" data-wx-block="showcase-video">
    @if ($heading)
        <h2 class="b-showcase-video__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-video__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-video__frame">
        @if ($clip)
            <x-webx-video :file="$clip" :poster="$picture" :title="$heading ?: null" :ratio="$shape" />
        @elseif ($address !== '')
            <x-webx-video :src="$address" :poster="$picture" :title="$heading ?: null" :ratio="$shape" />
        @endif
    </div>
</section>

styles:
.b-showcase-video {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

